window.SAOMD_STORIES[410401501]={"id":410401501,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401501:1:1","speaker":"Urdr","text":"Even mere knowledge of this power\ncould lead to calamity.","pose":20330107,"background":"bg_event_urtharbrunnr","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"即使仅仅了解这种力量也可能导致灾难。"}]},{"id":2,"order":2,"actions":[{"uid":"410401501:2:1","speaker":"Urdr","text":"Thus, we gods ensure that all\nthose who come into contact with\nit have their memories erased.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"所以我们诸神保证所有接触过它的人都会被抹去记忆。"}]},{"id":3,"order":3,"actions":[{"uid":"410401501:3:1","speaker":"Eugeo","text":"I don't want to have my memory\nerased! Is there nothing we can\ndo?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我不想我的记忆被抹去！我们无能为力吗？"},{"uid":"410401501:3:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410401501:4:1","speaker":"Urdr","text":"I am eternally grateful to you.\nHowever, there is no changing\nyour sad fate.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我永远感激你。然而，这并不能改变你悲惨的命运。"}]},{"id":5,"order":5,"actions":[{"uid":"410401501:5:1","speaker":"Urdr","text":"This was decided long ago, when\nthe Divine Objects were first\nforged...","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这在很久以前，神器刚被锻造的时候就已经决定了……"}]},{"id":6,"order":6,"actions":[{"uid":"410401501:6:1","speaker":"Alice","text":"So this is one of the rules of\nthis world. If that is the case,\nthere is nothing we can do.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来这就是这个世界的规则之一。如果真是这样的话，我们也无能为力。"},{"uid":"410401501:6:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410401501:7:1","speaker":"Eugeo","text":"You're just going to give up,\nAlice? Sit back and let our\nmemories be destroyed?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝，你就这么放弃吗？坐视我们的记忆被摧毁？"}]},{"id":8,"order":8,"actions":[{"uid":"410401501:8:1","speaker":"Alice","text":"Of course, this does not sit well\nwith me. But we must return to\nour world eventually...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"当然，这不适合我。但我们终究还是要回到自己的世界……"}]},{"id":9,"order":9,"actions":[{"uid":"410401501:9:1","speaker":"Alice","text":"Though our time here was well\nspent, our memories of this place\nare unnecessary in our world.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"虽然我们在这里度过了美好的时光，但这里的记忆在我们的世界里是不必要的。"}]},{"id":10,"order":10,"actions":[{"uid":"410401501:10:1","speaker":"Eugeo","text":"A-Alice!! You can't mean that!","pose":105302062,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"A-爱丽丝！！你不可能是这个意思！"}]},{"id":11,"order":11,"actions":[{"uid":"410401501:11:1","speaker":"Asuna","text":"...","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."},{"uid":"410401501:11:2","speaker":"Kirito","text":"","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410401501:12:1","speaker":"Kirito","text":"...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401501:12:2","speaker":"Asuna","text":"","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410401501:13:1","speaker":"Urdr","text":"Brave warriors, allow me to look\nafter those six Divine Objects.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"勇敢的战士们，请让我看管那六件神器。"}]},{"id":14,"order":14,"actions":[{"uid":"410401501:14:1","speaker":"Kirito","text":"Huh? But I thought that powerful\nmonsters were attracted to them.","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊？但我认为强大的怪物会被它们吸引。"},{"uid":"410401501:14:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":15,"order":15,"actions":[{"uid":"410401501:15:1","speaker":"Kirito","text":"Isn't that why it was better that\nwe hold onto them, until they're\nall collected?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这难道不是我们最好把它们留着，直到它们全部收集起来吗？"},{"uid":"410401501:15:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401501:16:1","speaker":"Urdr","text":"Thanks to my little sisters, we\nmade a shrine that can suppress\ntheir power, albeit temporarily.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"多亏了我的妹妹们，我们建造了一座神殿，可以压制她们的力量，尽管是暂时的。"}]},{"id":17,"order":17,"actions":[{"uid":"410401501:17:1","speaker":"Urdr","text":"As long as we keep the Divine\nObjects inside, there should be\nno trouble.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"只要我们把神器留在里面，应该就没有问题。"}]},{"id":18,"order":18,"actions":[{"uid":"410401501:18:1","speaker":"Asuna","text":"I see. That's good to hear.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"原来如此。很高兴听到这个消息。"},{"uid":"410401501:18:2","speaker":"Kirito","text":"","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410401501:19:1","speaker":"Kirito","text":"Yeah...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……"},{"uid":"410401501:19:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":20,"order":20,"actions":[{"uid":"410401501:20:1","speaker":"Urdr","text":"Then, if you would be so kind as\nto let me have them...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"那么，如果你能好心让我拥有它们的话……"}]},{"id":21,"order":21,"actions":[{"uid":"410401501:21:1","speaker":"Kirito","text":"Well... Sure.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……当然。"},{"uid":"410401501:21:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410401501:22:1","speaker":"Kirito","text":"...","pose":10011506,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401501:22:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":23,"order":23,"actions":[{"uid":"410401501:23:1","speaker":"Asuna","text":"Kirito! I thought you said you\nwere busy today, but here you are.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人！我以为你说你今天很忙，但你来了。"}]},{"id":24,"order":24,"actions":[{"uid":"410401501:24:1","speaker":"Kirito","text":"I couldn't help worry about Alice\nand Eugeo. How are they?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我忍不住担心爱丽丝和尤吉欧。他们怎么样？"}]},{"id":25,"order":25,"actions":[{"uid":"410401501:25:1","speaker":"Asuna","text":"Still sleeping away.\nThey're taking longer and longer\nto wake up.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"还在睡觉呢。他们醒来的时间越来越长。"}]},{"id":26,"order":26,"actions":[{"uid":"410401501:26:1","speaker":"Asuna","text":"Staying in this world must really\nbe taking its toll on them...","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"留在这个世界上，对他们来说，一定是很痛苦的……"}]},{"id":27,"order":27,"actions":[{"uid":"410401501:27:1","speaker":"Kirito","text":"And we still have no idea where\nthe last Divine Object could be...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"而且我们仍然不知道最后一个神器可能在哪里......"}]},{"id":28,"order":28,"actions":[{"uid":"410401501:28:1","speaker":"Asuna","text":"I know. Not even with Liz, Leafa,\nYuuki, and Rain helping us out.","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我知道。即使有莉兹、莉法、优纪和蕾茵帮助我们也没有。"}]},{"id":29,"order":29,"actions":[{"uid":"410401501:29:1","speaker":"Kirito","text":"Ever since then, we've split up\nover the whole game to try and\nfind out all we can.","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"从那时起，我们就在整个游戏中分头行动，试图找出我们能找到的一切。"}]},{"id":30,"order":30,"actions":[{"uid":"410401501:30:1","speaker":"Kirito","text":"I was sure we could find out\neverything happening in ALO with\neveryone's help, and yet...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"本来以为在大家的帮助下我们可以查出ALO发生的一切，但是……"}]},{"id":31,"order":31,"actions":[{"uid":"410401501:31:1","speaker":"Asuna","text":"...What is it you're trying to\nsay?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"……你想说什么？"}]},{"id":32,"order":32,"actions":[{"uid":"410401501:32:1","speaker":"Kirito","text":"I'm saying that it won't be nearly\nas easy to find the seventh Divine\nObject.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我是说，想要找到第七件神物可没那么容易。"}]},{"id":33,"order":33,"actions":[{"uid":"410401501:33:1","speaker":"Kirito","text":"It may be hidden somewhere we\ncan't even imagine...or somewhere\nwe would never think to look.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"它可能隐藏在我们无法想象的地方……或者我们永远不会想到去寻找的地方。"}]},{"id":34,"order":34,"actions":[{"uid":"410401501:34:1","speaker":"Asuna","text":"You may be right...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你可能是对的……"},{"uid":"410401501:34:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410401501:35:1","speaker":"Alice","text":"Good morning...","pose":105401062,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"早上好……"}]},{"id":36,"order":36,"actions":[{"uid":"410401501:36:1","speaker":"Eugeo","text":"Sorry about this...\nI'm still kind of sleepy...","pose":105302062,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"抱歉……我还是有点困……"}]},{"id":37,"order":37,"actions":[{"uid":"410401501:37:1","speaker":"Asuna","text":"Oh... It's okay...","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦……没关系……"},{"uid":"410401501:37:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410401501:38:1","speaker":"Kirito","text":"Don't push yourselves too hard.\nIf you need rest, head back to\nbed.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"别给自己太大压力。如果您需要休息，请回到床上。"}]},{"id":39,"order":39,"actions":[{"uid":"410401501:39:1","speaker":"Alice","text":"There is no time for that. After\nall, we still have yet to find the\nseventh Divine Object.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"没时间。毕竟我们还没有找到第七个神器。"},{"uid":"410401501:39:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410401501:40:1","speaker":"Kirito","text":"Well, yeah, that's true...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，是的，确实如此……"},{"uid":"410401501:40:2","speaker":"Asuna","text":"","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410401501:41:1","speaker":"Eugeo","text":"Even as we speak, someone could\nbe using it for evil purposes.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"就在我们说话的时候，有人可能会利用它来达到邪恶的目的。"},{"uid":"410401501:41:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410401501:42:1","speaker":"Eugeo","text":"I'm not going to let a little\ndrowsiness hold me back.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我不会让一点睡意阻碍我。"}]},{"id":43,"order":43,"actions":[{"uid":"410401501:43:1","speaker":"Alice","text":"I couldn't agree more.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我非常同意。"}]},{"id":44,"order":44,"actions":[{"uid":"410401501:44:1","speaker":"Asuna","text":"Well... If you insist.","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好吧……如果你坚持的话。"},{"uid":"410401501:44:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410401501:45:1","speaker":"Kirito","text":"One thing seems clear: we need to\nbe smarter about how we search.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有一件事似乎很清楚：我们需要更聪明地搜索。"}]},{"id":46,"order":46,"actions":[{"uid":"410401501:46:1","speaker":"Kirito","text":"So far, we've covered just about\nall of ALO during our search for\nthe other Objects.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"到目前为止，我们在寻找其他Object的过程中已经几乎涵盖了ALO的全部内容。"}]},{"id":47,"order":47,"actions":[{"uid":"410401501:47:1","speaker":"Kirito","text":"That includes the surface,\nJotunheimr... All that's left is\nthe sea and Thrymheim...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"包括地表在内，幽兹海姆……剩下的就是大海和Thrymheim了……"}]},{"id":48,"order":48,"actions":[{"uid":"410401501:48:1","speaker":"Kirito","text":"And based on everything else\nthat's happened, those last two\nseem pretty unlikely.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"根据所发生的一切，后两个似乎不太可能。"}]},{"id":49,"order":49,"actions":[{"uid":"410401501:49:1","speaker":"Alice","text":"How can you be so sure?\nDidn't we find one in Asuka\nEmpire?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你怎么这么确定？飞鸟帝国不是找到了吗？"},{"uid":"410401501:49:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410401501:50:1","speaker":"Kirito","text":"Only because that Hi-Mob took\nit there.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"只是因为那个Hi-Mob把它带到了那里。"},{"uid":"410401501:50:2","speaker":"Kirito","text":"I doubt that sort of\nthing would have happened again.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我怀疑这种事情会再次发生。"},{"uid":"410401501:50:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410401501:51:1","speaker":"Asuna","text":"Hmm... Why don't we start by\nremembering where we found the\nother six Objects?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯...我们为什么不先记住其他六个物体是在哪里找到的呢？"}]},{"id":52,"order":52,"actions":[{"uid":"410401501:52:1","speaker":"Eugeo","text":"You think that might help us\nfigure out where the last one is?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你觉得这可以帮助我们找出最后一个在哪里吗？"},{"uid":"410401501:52:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410401501:53:1","speaker":"Kirito","text":"I think it might. You two don't\nmind, do you?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我觉得有可能。你们两个不介意吧？"},{"uid":"410401501:53:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410401501:54:1","speaker":"Alice","text":"You're not just looking for a way\nto get us to stop and rest, are\nyou?","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你不会只是想找办法让我们停下来休息吧？"},{"uid":"410401501:54:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410401501:55:1","speaker":"Kirito","text":"O-Of course not! Don't read so\nmuch into it!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊、当然不是！不要读那么多！"},{"uid":"410401501:55:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":56,"order":56,"actions":[{"uid":"410401501:56:1","speaker":"Alice","text":"Very well then...\nLet's get started.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那好吧……开始吧。"},{"uid":"410401501:56:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410401501:57:1","speaker":"Kirito","text":"Let's see... We found the\nfirst one in Jotunheimr.","pose":10011507,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我看看……我们在幽兹海姆找到了第一个。"},{"uid":"410401501:57:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410401501:58:1","speaker":"Alice","text":"That was also where Eugeo and I\nfirst entered this world.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那也是我和尤吉欧第一次进入这个世界的地方。"},{"uid":"410401501:58:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410401501:59:1","speaker":"Kirito","text":"That really makes it the place\nwhere all this began...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这确实是这一切开始的地方……"},{"uid":"410401501:59:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410401501:60:1","speaker":"Eugeo","text":"I remember there were many\nferocious monsters running rampant\nthere.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我记得那里有很多凶猛的怪物横行。"},{"uid":"410401501:60:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410401501:61:1","speaker":"Asuna","text":"Yup. Way stronger ones spawn there\nthan you run into on the surface.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的。那里的生成物比你在地表遇到的要强大得多。"},{"uid":"410401501:61:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":62,"order":62,"actions":[{"uid":"410401501:62:1","speaker":"Alice","text":"Looking back on it now, it seems\nappropriate that a Divine Object\nwas located there.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"现在回想起来，神器放在那里似乎是合适的。"},{"uid":"410401501:62:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410401501:63:1","speaker":"Alice","text":"I've been fighting fierce monsters\nsince I arrived, so I didn't find\nit unusual at the time.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我来之后一直在和凶猛的怪物战斗，所以当时并没有觉得有什么异常。"}]},{"id":64,"order":64,"actions":[{"uid":"410401501:64:1","speaker":"Asuna","text":"Well, you two both have Sacred\nArts, Enhance Armament, and that\namazing technique... What was it?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，你们两个都有神术，武装完全支配术，还有那个神奇的功法……是什么？"},{"uid":"410401501:64:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410401501:65:1","speaker":"Asuna","text":"Oh yeah, Release Recollection!\nSo I guess they weren't much of a\nfight for you.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦对了，记忆解放术！所以我想他们对你来说并不是什么大不了的斗争。"}]},{"id":66,"order":66,"actions":[{"uid":"410401501:66:1","speaker":"Kirito","text":"The next Divine Object was in the\nsouthern seas...along with a\ngigantic whale monster.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"下一个神器是在南海……还有一只巨大的鲸鱼怪物。"}]},{"id":67,"order":67,"actions":[{"uid":"410401501:67:1","speaker":"Eugeo","text":"I remember how Kirito and I got\nswallowed up, and we had to attack\nit both inside and out to escape.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我记得我和桐人是如何被吞噬的，我们必须里里外外地攻击它才能逃脱。"},{"uid":"410401501:67:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":68,"order":68,"actions":[{"uid":"410401501:68:1","speaker":"Alice","text":"As I recall, the nearby villagers\ntold us that it too had recently\nappeared out of nowhere.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我记得附近的村民告诉我们，它也是最近突然出现的。"}]},{"id":69,"order":69,"actions":[{"uid":"410401501:69:1","speaker":"Asuna","text":"It does feel like the Divine\nObjects always show up alongside\nreally tough enemies.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"感觉神器总是和强敌一起出现。"},{"uid":"410401501:69:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410401501:70:1","speaker":"Eugeo","text":"I believe we found the next one in\nthe land of the Leprechauns.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我相信我们在妖精之地找到了下一个。"},{"uid":"410401501:70:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401501:71:1","speaker":"Kirito","text":"They told us that they had already\ntaken it for themselves, and had\nno intention of giving it up.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们告诉我们，他们已经占为己有，并没有打算放弃。"},{"uid":"410401501:71:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410401501:72:1","speaker":"Kirito","text":"We told them we would take it by\nforce if we had to, but\nfortunately we avoided conflict.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们告诉他们，如果有必要的话我们会武力夺取，但幸运的是我们避免了冲突。"}]},{"id":73,"order":73,"actions":[{"uid":"410401501:73:1","speaker":"Kirito","text":"They saw how dangerous it was,\nand agreed to let us have it.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们看到它有多危险，就同意让我们拥有它。"}]},{"id":74,"order":74,"actions":[{"uid":"410401501:74:1","speaker":"Asuna","text":"I don't know what we would have\ndone without your quick thinking.\nYou two really helped us out.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我不知道如果没有你的敏捷思考我们会做出什么事。你们两个真的帮了我们大忙。"}]},{"id":75,"order":75,"actions":[{"uid":"410401501:75:1","speaker":"Alice","text":"It was nothing special, honestly.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"说实话，没什么特别的。"},{"uid":"410401501:75:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410401501:76:1","speaker":"Eugeo","text":"Besides, Liz and Rain helped us\ntoo, even though they were both\nLeprechauns themselves.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"另外，莉兹和蕾茵也帮助了我们，尽管他们本身都是妖精。"}]},{"id":77,"order":77,"actions":[{"uid":"410401501:77:1","speaker":"Asuna","text":"Now, the fourth one... That showed\nup in a treasure chest at the\nDread Bastion during Halloween.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"第四个……万圣节期间出现在恐惧堡垒的宝箱里。"},{"uid":"410401501:77:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410401501:78:1","speaker":"Eugeo","text":"I couldn't believe my eyes when\nI saw Aincrad had been\ntransformed.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"当我看到艾恩葛朗特变身时，我简直不敢相信自己的眼睛。"},{"uid":"410401501:78:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410401501:79:1","speaker":"Kirito","text":"Not to mention all the Bastion's\ndemons turning into even more\nferocious monsters...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"更何况堡垒里的恶魔都变成了更加凶猛的怪物……"},{"uid":"410401501:79:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":80,"order":80,"actions":[{"uid":"410401501:80:1","speaker":"Asuna","text":"Yeah, it was like the Halloween\ndemons had been swapped out for\nDivine Object monsters.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，就像万圣节恶魔换成了神器怪物一样。"}]},{"id":81,"order":81,"actions":[{"uid":"410401501:81:1","speaker":"Eugeo","text":"...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"..."},{"uid":"410401501:81:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410401501:82:1","speaker":"Asuna","text":"Is something wrong, Eugeo?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有什么问题吗，尤吉欧？"},{"uid":"410401501:82:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410401501:83:1","speaker":"Eugeo","text":"Oh, no, it's nothing... I was just\nthinking \"Did that really\nhappen...?\"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哦，不，没什么……我只是在想“真的发生过这种事吗……？”"},{"uid":"410401501:83:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410401501:84:1","speaker":"Kirito","text":"...?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...?"},{"uid":"410401501:84:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410401501:85:1","speaker":"Eugeo","text":"Okay, I remember now...\nGo on, keep talking.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好吧，我想起来了……继续说吧。"},{"uid":"410401501:85:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401501:86:1","speaker":"Kirito","text":"R-Right... Well, we found the\nfifth one when we helped Seven\nwhile she sang Christmas carols.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对、对……好吧，我们在帮助赛玟唱圣诞颂歌时找到了第五个。"},{"uid":"410401501:86:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410401501:87:1","speaker":"Asuna","text":"That was when the Hi-Mob who was\nafter the Divine Objects showed up\nand attacked the carolers.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"就在这时，追捕神器的Hi-Mob出现并袭击了颂歌者。"}]},{"id":88,"order":88,"actions":[{"uid":"410401501:88:1","speaker":"Asuna","text":"At first I thought it was just\nbecause those Pookas' songs could\nhurt his monsters...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"一开始我以为只是因为那些Pookas的歌会伤害他的怪物……"}]},{"id":89,"order":89,"actions":[{"uid":"410401501:89:1","speaker":"Asuna","text":"But it all ended up leading to us\nto the fifth Divine Object.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但这一切最终让我们获得了第五个神器。"}]},{"id":90,"order":90,"actions":[{"uid":"410401501:90:1","speaker":"Alice","text":"It did? Really?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是吗？真的吗？"},{"uid":"410401501:90:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401501:91:1","speaker":"Kirito","text":"Yeah. Seven found it in the last\nchurch's basement, and agreed to\nlet us have it.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。 赛玟在最后一个教堂的地下室找到了它，并同意让我们拥有它。"},{"uid":"410401501:91:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410401501:92:1","speaker":"Kirito","text":"You...were there too, Alice.\nDon't you remember?","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你……也在场，爱丽丝。你不记得了吗？"}]},{"id":93,"order":93,"actions":[{"uid":"410401501:93:1","speaker":"Alice","text":"O-Oh, right. It was so long ago,\nI'm afraid it completely slipped\nmy mind...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哦哦，对了。时间太久远了，恐怕我已经完全忘记了……"},{"uid":"410401501:93:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410401501:94:1","speaker":"Asuna","text":"...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."},{"uid":"410401501:94:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":95,"order":95,"actions":[{"uid":"410401501:95:1","speaker":"Kirito","text":"Oh no... Don't tell me...","pose":10011506,"background":"bg_13_coral_lake","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦不……别告诉我……"},{"uid":"410401501:95:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410401501:96:1","speaker":"Asuna","text":"Calm down, Kirito. We don't know\nfor sure that they're losing their\nmemories.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"冷静点，桐人。我们不确定他们是否正在失去记忆。"}]},{"id":97,"order":97,"actions":[{"uid":"410401501:97:1","speaker":"Asuna","text":"They could just be really tired,\nlike they said.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"就像他们说的那样，他们可能真的很累。"}]},{"id":98,"order":98,"actions":[{"uid":"410401501:98:1","speaker":"Kirito","text":"But, Urdr said that those who come\ninto contact with the Objects'\npower lose their memories.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是，乌尔德说，接触到Objects力量的人就会失去记忆。"}]},{"id":99,"order":99,"actions":[{"uid":"410401501:99:1","speaker":"Kirito","text":"And outside those two, only\nplayers have been in much contact\nwith them.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"除了他们两人之外，只有玩家和他们接触比较多。"}]},{"id":100,"order":100,"actions":[{"uid":"410401501:100:1","speaker":"Kirito","text":"Their memories might even be\nsuffering all the more because of\nthe corruption of their data!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们的记忆甚至可能因为数据的损坏而更加痛苦！"}]},{"id":101,"order":101,"actions":[{"uid":"410401501:101:1","speaker":"Asuna","text":"...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."}]},{"id":102,"order":102,"actions":[{"uid":"410401501:102:1","speaker":"Kirito","text":"I-I'm sorry, Asuna. I didn't mean\nto shout...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对不起，亚丝娜。我不是故意要喊的..."}]},{"id":103,"order":103,"actions":[{"uid":"410401501:103:1","speaker":"Kirito","text":"I just... It feels like the\nsituation could be a lot worse\nthan we'd imagined.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我只是……感觉情况可能比我们想象的还要糟糕。"}]},{"id":104,"order":104,"actions":[{"uid":"410401501:104:1","speaker":"Asuna","text":"It could be... But since we don't\nhave any leads, there's only one\nthing we can do right now.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有可能……但是因为我们没有任何线索，所以现在我们能做的只有一件事。"}]},{"id":105,"order":105,"actions":[{"uid":"410401501:105:1","speaker":"Kirito","text":"Really? What's that?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的吗？那是什么？"}]},{"id":106,"order":106,"actions":[{"uid":"410401501:106:1","speaker":"Asuna","text":"Let's try visiting Urdr again.\nShe's holding onto the Divine\nObjects for us.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们再访问一下乌尔德吧。她正在为我们保管神圣物品。"}]},{"id":107,"order":107,"actions":[{"uid":"410401501:107:1","speaker":"Asuna","text":"It's worth seeing if that might\nhave triggered a new event.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"值得看看这是否会触发新的事件。"}]},{"id":108,"order":108,"actions":[{"uid":"410401501:108:1","speaker":"Kirito","text":"...Yeah, good point. I guess\nthat's all we've got to go on\nright now.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……嗯，说得好。我想这就是我们现在要做的一切。"},{"uid":"410401501:108:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410401501:109:1","speaker":"Alice","text":"You two are going back to see the\ngoddess of this realm once more,\naren't you?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你们两个又要回去见见这个界的女神了，是吗？"}]},{"id":110,"order":110,"actions":[{"uid":"410401501:110:1","speaker":"Kirito","text":"Alice, Eugeo... How long have you\nbeen listening?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝、尤吉欧……听了多久了？"},{"uid":"410401501:110:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410401501:111:1","speaker":"Eugeo","text":"...From the part about going to\nsee Urdr again.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"...从关于再去见乌尔德的部分。"},{"uid":"410401501:111:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410401501:112:1","speaker":"Asuna","text":"O-Oh...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"噢噢……"},{"uid":"410401501:112:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410401501:113:1","speaker":"Alice","text":"Naturally, I shall accompany you.\nI refuse to lounge about doing\nnothing any more.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我当然陪你。我拒绝再无所事事地闲逛。"},{"uid":"410401501:113:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410401501:114:1","speaker":"Eugeo","text":"I'll go too. I'm already feeling a\nlot better.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也去。我已经感觉好多了。"}]},{"id":115,"order":115,"actions":[{"uid":"410401501:115:1","speaker":"Kirito","text":"...Okay then. Let's all go there\ntogether.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……好吧。我们大家一起去那里吧。"},{"uid":"410401501:115:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401501:116:1","speaker":"Kirito","text":"Sugu said she's free right now,\nso I'll have her join us too.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"小直说她现在有空，所以我就让她也加入我们吧。"}]},{"id":117,"order":117,"actions":[{"uid":"410401501:117:1","speaker":"Kirito","text":"Urdr! Are you there?!","pose":10011505,"background":"bg_event_urtharbrunnr","item":"","illustration":"","speaker_zh":"桐人","text_zh":"乌尔德！你在吗？！"},{"uid":"410401501:117:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:117:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410401501:118:1","speaker":"Leafa","text":"That's odd. She's always been here\nbefore...","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"这很奇怪。她以前一直来过这里..."}]},{"id":119,"order":119,"actions":[{"uid":"410401501:119:1","speaker":"Eugeo","text":"She did say she had made a shrine\nthat could contain the six Divine\nObjects' power, right?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"她确实说过，她制作了一座能够容纳六件神物力量的神龛吧？"},{"uid":"410401501:119:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":120,"order":120,"actions":[{"uid":"410401501:120:1","speaker":"Eugeo","text":"Maybe we'll find her there?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"也许我们能在那里找到她？"}]},{"id":121,"order":121,"actions":[{"uid":"410401501:121:1","speaker":"Alice","text":"Where could this shrine be?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个神社会在哪里呢？"}]},{"id":122,"order":122,"actions":[{"uid":"410401501:122:1","speaker":"Kirito","text":"Hey, there's a small building over\nby that path.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嘿，那条路旁边有一栋小楼。"},{"uid":"410401501:122:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:122:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410401501:123:1","speaker":"Asuna","text":"Maybe that's it. Let's go see.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"也许就是这样吧。我们去看看吧。"}]},{"id":124,"order":124,"actions":[{"uid":"410401501:124:1","speaker":"???","text":"Sister?! What are you doing?!","pose":2,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"？？？","text_zh":"姐姐？！你在干什么？！"},{"uid":"410401501:124:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401501:124:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:124:4","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410401501:125:1","speaker":"???","text":"What must be done, Skuld.\nNow, give me your Valkyrie power!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"必须做什么，Skuld。现在，请赐予我你的瓦尔基里之力吧！"}]},{"id":126,"order":126,"actions":[{"uid":"410401501:126:1","speaker":"Kirito","text":"Who was that...?","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那是谁……？"}]},{"id":127,"order":127,"actions":[{"uid":"410401501:127:1","speaker":"Asuna","text":"And what's all the commotion\nabout?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那么骚动是为了什么？"}]},{"id":128,"order":128,"actions":[{"uid":"410401501:128:1","speaker":"Leafa","text":"Wasn't that Skuld talking?\nThe youngest of the three Hill\nGiant sisters?","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"那不是Skuld在说话吗？山丘巨人三姐妹中最小的一个？"}]},{"id":129,"order":129,"actions":[{"uid":"410401501:129:1","speaker":"Alice","text":"It came from over there.\nLet's hurry.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"从那边来的。我们快点吧。"},{"uid":"410401501:129:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410401501:130:1","speaker":"Urdr","text":"As one of the Valkyries, I shall\nrid the world of impurities...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"作为女武神的一员，我要清除世界上的杂质……"}]},{"id":131,"order":131,"actions":[{"uid":"410401501:131:1","speaker":"Skuld","text":"Sister, please, I beg you!\nYou mustn't use the Divine Objects\nin this way!","pose":20440107,"background":"","item":"","illustration":"","speaker_zh":"斯库尔德","text_zh":"姐姐，求求你了！神器不可以这样使用！"}]},{"id":132,"order":132,"actions":[{"uid":"410401501:132:1","speaker":"","text":"","pose":0,"background":"","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410401501:133:1","speaker":"Skuld","text":"Nng... My power is...fading...","pose":20440106,"background":"","item":"","illustration":"","speaker_zh":"斯库尔德","text_zh":"呜……我的力量……正在衰退……"}]},{"id":134,"order":134,"actions":[{"uid":"410401501:134:1","speaker":"Skuld","text":"Argh!","pose":20440108,"background":"","item":"","illustration":"","speaker_zh":"斯库尔德","text_zh":"啊啊！"}]},{"id":135,"order":135,"actions":[{"uid":"410401501:135:1","speaker":"Urdr","text":"Now, Skuld's Valkyrie power is\nall mine...","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在，斯库尔德的瓦尔基里之力都是我的了……"}]},{"id":136,"order":136,"actions":[{"uid":"410401501:136:1","speaker":"Kirito","text":"What's going on here?!","pose":10011508,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是怎么回事？！"},{"uid":"410401501:136:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:136:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":137,"order":137,"actions":[{"uid":"410401501:137:1","speaker":"Asuna","text":"Urdr?! What happened to Skuld?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"乌尔德？！斯库尔德怎么了？！"},{"uid":"410401501:137:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":138,"order":138,"actions":[{"uid":"410401501:138:1","speaker":"Urdr","text":"So, you've figured it out.\nBut I'm afraid you're too late.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"所以，你已经明白了。但恐怕你来得太晚了。"}]},{"id":139,"order":139,"actions":[{"uid":"410401501:139:1","speaker":"Urdr","text":"The Divine Objects are mine. Soon,\nI shall use the Valkyries' power\nto complete the Rite of Release.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"神器是我的。很快，我就会借助女武神的力量，完成解放仪式。"}]},{"id":140,"order":140,"actions":[{"uid":"410401501:140:1","speaker":"Urdr","text":"Thus will my goal of ridding the\nworld of impurities be realized!","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这样我去除世间杂质的目标就达到了！"}]},{"id":141,"order":141,"actions":[{"uid":"410401501:141:1","speaker":"Kirito","text":"What are you talking about?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你说什么？！"},{"uid":"410401501:141:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:141:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":142,"order":142,"actions":[{"uid":"410401501:142:1","speaker":"Alice","text":"Goddess of this realm...I'm afraid\nyou're not making sense.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个境界的女神……恐怕你没讲道理。"},{"uid":"410401501:142:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":143,"order":143,"actions":[{"uid":"410401501:143:1","speaker":"Alice","text":"Did you not build this place in\norder to temporarily seal away\nthe Divine Objects' power?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你建造这个地方不是为了暂时封锁神器的力量吗？"},{"uid":"410401501:143:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":144,"order":144,"actions":[{"uid":"410401501:144:1","speaker":"Urdr","text":"Brave warriors... You have done\nwell up to this point.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"勇敢的战士们……到目前为止你们已经做得很好了。"}]},{"id":145,"order":145,"actions":[{"uid":"410401501:145:1","speaker":"Urdr","text":"But from here on, the six of us\nshall handle this matter.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"不过从现在开始，这件事就由我们六个人来处理。"}]},{"id":146,"order":146,"actions":[{"uid":"410401501:146:1","speaker":"Urdr","text":"As for you... You can return to\nthe abyss of death!","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"至于你……你可以回到死亡深渊了！"}]},{"id":147,"order":147,"actions":[{"uid":"410401501:147:1","speaker":"Asuna","text":"Wh-What do you mean?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什、什么意思？！"},{"uid":"410401501:147:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401501:147:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410401501:148:1","speaker":"Skuld","text":"Something is wrong with Urdr...\nOut of nowhere, she began chanting\na strange spell at the Objects...","pose":20440107,"background":"","item":"","illustration":"","speaker_zh":"斯库尔德","text_zh":"乌尔德出了点问题……她突然开始对着物体念出奇怪的咒语……"}]},{"id":149,"order":149,"actions":[{"uid":"410401501:149:1","speaker":"Skuld","text":"And stole my Valkyrie power...","pose":20440107,"background":"","item":"","illustration":"","speaker_zh":"斯库尔德","text_zh":"还偷走了我的瓦尔基里力量……"}]},{"id":150,"order":150,"actions":[{"uid":"410401501:150:1","speaker":"Leafa","text":"Valkyries... They were tasked with\nchoosing heroes slain in battle\nand bringing them to Valhalla.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"瓦尔基里……他们的任务是挑选在战斗中阵亡的英雄并将他们带到瓦尔哈拉。"},{"uid":"410401501:150:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401501:150:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":151,"order":151,"actions":[{"uid":"410401501:151:1","speaker":"Leafa","text":"I'm pretty sure that Skuld was one\nof them.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我很确定Skuld就是其中之一。"}]},{"id":152,"order":152,"actions":[{"uid":"410401501:152:1","speaker":"Asuna","text":"Okay, but why would...","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好吧，但是为什么会……"},{"uid":"410401501:152:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410401501:153:1","speaker":"Urdr","text":"Hear me, valiant gods five!\nNow is the time to awaken!","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"听我说，勇猛的五神！现在是觉醒的时候了！"}]},{"id":154,"order":154,"actions":[{"uid":"410401501:154:1","speaker":"Kirito","text":"Wh-What is this?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这、这是什么？！"},{"uid":"410401501:154:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401501:154:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":155,"order":155,"actions":[{"uid":"410401501:155:1","speaker":"Alice","text":"This immense power... It's the\nsame as that of the monsters\nattracted to the Divine Objects!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这巨大的力量……和神器吸引的怪物一样！"},{"uid":"410401501:155:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":156,"order":156,"actions":[{"uid":"410401501:156:1","speaker":"Eugeo","text":"Everyone, look! Over there!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"大家看！在那边！"}]},{"id":157,"order":157,"actions":[{"uid":"410401501:157:1","speaker":"Kirito","text":"No way...!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不可能……！"},{"uid":"410401501:157:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401501:157:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]}]};
